COLLECTION_NAME = "VERTICALFRAME"


def build():
    scn = bpy.context.scene
    scn.unit_settings.system = "METRIC"
    scn.unit_settings.length_unit = "METERS"

    coll = bpy.data.collections.get(COLLECTION_NAME)
    if coll is None:
        coll = bpy.data.collections.new(COLLECTION_NAME)
        bpy.context.scene.collection.children.link(coll)

    created = []
    for name, flat_v, flat_f in PARTS:
        verts = [(flat_v[i], flat_v[i+1], flat_v[i+2]) for i in range(0, len(flat_v), 3)]
        faces = [(flat_f[i], flat_f[i+1], flat_f[i+2]) for i in range(0, len(flat_f), 3)]
        mesh = bpy.data.meshes.new(name + "_mesh")
        mesh.from_pydata(verts, [], faces)
        mesh.validate()
        mesh.update()
        obj = bpy.data.objects.new(name, mesh)
        coll.objects.link(obj)
        created.append(obj)

    root = bpy.data.objects.new(COLLECTION_NAME + "_root", None)
    root.empty_display_size = 0.3
    coll.objects.link(root)
    for obj in created:
        obj.parent = root

    print("VERTICALFRAME: built %d parts" % len(created))
    return root


if __name__ == "__main__":
    build()
